const items = $input.all();
const startUrls = items.map(item => ({
    url: 'https://' + item.json.domain
}));

return {
    groupByPage: true,
    includeContactText: true,
    solveCloudflare: false,
    startUrls: startUrls,
    stayOnDomain: true,
    useStealth: true
};

let domainMap = new Map();

// Helper to normalize phone numbers
function normalizePhone(phoneStr) {
    if (!phoneStr) return null;
    let clean = String(phoneStr).replace(/\n/g, ' ').replace(/[^\d]/g, '');
    if (clean.length === 11 && clean.startsWith('1')) {
        clean = clean.substring(1);
    }
    if (clean.length === 10) {
        return `(${clean.substring(0,3)}) ${clean.substring(3,6)}-${clean.substring(6)}`;
    }
    return null;
}

let inputItems = $input.all();
if (!inputItems || inputItems.length === 0) {
    return [];
}

inputItems.forEach(item => {
    let rawData = item.json;
    if (!rawData) return;

    // 1. Safe URL & Domain extraction
    let rawUrl = rawData.sourceUrl || rawData.url || '';
    if (!rawUrl) return;

    let cleanUrl = String(rawUrl).trim();
    let domain = '';
    try {
        if (!cleanUrl.startsWith('http')) {
            cleanUrl = 'https://' + cleanUrl;
        }
        let parsedUrl = new URL(cleanUrl);
        domain = parsedUrl.hostname.replace('www.', '').toLowerCase();
    } catch (e) {
        domain = cleanUrl.replace(/https?:\/\//, '').split('/')[0].toLowerCase();
    }

    if (!domain) return;

    // 2. Initialize Domain Entry with separate social fields
    if (!domainMap.has(domain)) {
        domainMap.set(domain, {
            sourceUrl: `https://${domain}`,
            companyName: '',
            emails: new Set(),
            phones: new Set(),
            addresses: new Set(),
            facebook: new Set(),
            instagram: new Set(),
            twitter: new Set(),
            youtube: new Set(),
            linkedin: new Set(),
            tiktok: new Set()
        });
    }

    let entry = domainMap.get(domain);

    // 3. Extract Company Name safely from pageTitle
    if (rawData.pageTitle && !entry.companyName) {
        let titleFull = String(rawData.pageTitle).trim();
        let cleanTitle = titleFull.split(/[:\|\-–]/)[0].trim();
        entry.companyName = cleanTitle || titleFull;
    }

    // 4. Safe Email Extraction
    let rawEmails = rawData.emails;
    if (rawEmails) {
        let emailList = Array.isArray(rawEmails) ? rawEmails : (typeof rawEmails === 'object' ? Object.values(rawEmails) : [String(rawEmails)]);
        emailList.forEach(e => {
            let emailStr = typeof e === 'object' && e !== null ? (e.url || e.email || '') : String(e);
            emailStr = emailStr.trim().toLowerCase().replace(/,+$/, '');
            if (emailStr && emailStr.includes('@') && emailStr !== 'empty' && !emailStr.includes('schema') && !emailStr.includes('example')) {
                entry.emails.add(emailStr);
            }
        });
    }

    // 5. Safe Phone Extraction
    let rawPhones = rawData.phones;
    if (rawPhones) {
        let phoneList = Array.isArray(rawPhones) ? rawPhones : (typeof rawPhones === 'object' ? Object.values(rawPhones) : [String(rawPhones)]);
        phoneList.forEach(p => {
            let pStr = String(p).trim();
            if (pStr.includes('\n')) {
                pStr = pStr.split('\n').pop();
            }
            let formattedPhone = normalizePhone(pStr);
            if (formattedPhone) {
                entry.phones.add(formattedPhone);
            }
        });
    }

    // 6. Safe Address Extraction
    let rawAddresses = rawData.addresses;
    if (rawAddresses) {
        let addrList = Array.isArray(rawAddresses) ? rawAddresses : (typeof rawAddresses === 'object' ? Object.values(rawAddresses) : [String(rawAddresses)]);
        addrList.forEach(a => {
            let aStr = String(a).trim().replace(/\s+/g, ' ');
            if (aStr.includes(':') && !/^\d{2,6}/.test(aStr)) {
                aStr = aStr.split(':').slice(1).join(':').trim();
            }
            let lower = aStr.toLowerCase();
            let hasJunk = /(appointment|doctor|when dr|i had|stars|front desk|school|drive|p\.m|a\.m|after|before|click|contact|post|hour|day|month|year|freeway|feet|list|diagnos|ago|seen|trip|already|example|min|americans|adults|hg|have|that|you|over|than|miles)/i.test(lower);
            let isRealAddress = /^\d{2,6}\s+[A-Za-z0-9]/i.test(aStr);

            if (isRealAddress && !hasJunk && aStr.length >= 8 && aStr.length < 80) {
                let cleanAddr = aStr.toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
                entry.addresses.add(cleanAddr);
            }
        });
    }

    // 7. Categorized Socials Extraction (Platform-wise separation & cleaning)
    let rawSocials = rawData.socials;
    if (rawSocials && typeof rawSocials === 'object') {
        for (let platform in rawSocials) {
            let platformData = rawSocials[platform];
            if (platformData) {
                let itemsList = Array.isArray(platformData) ? platformData : Object.values(platformData);
                itemsList.forEach(itemObj => {
                    let socialUrl = '';
                    if (itemObj && typeof itemObj === 'object' && itemObj.url) {
                        socialUrl = String(itemObj.url).trim();
                    } else if (typeof itemObj === 'string' && itemObj.startsWith('http')) {
                        socialUrl = itemObj.trim();
                    }

                    if (socialUrl && !socialUrl.includes('/sharer') && !socialUrl.includes('intent/tweet') && !socialUrl.includes('pin/create/button')) {
                        let lowerUrl = socialUrl.toLowerCase();
                        if (lowerUrl.includes('facebook.com')) {
                            entry.facebook.add(socialUrl);
                        } else if (lowerUrl.includes('instagram.com')) {
                            entry.instagram.add(socialUrl);
                        } else if (lowerUrl.includes('twitter.com') || lowerUrl.includes('x.com')) {
                            entry.twitter.add(socialUrl);
                        } else if (lowerUrl.includes('youtube.com')) {
                            entry.youtube.add(socialUrl);
                        } else if (lowerUrl.includes('linkedin.com')) {
                            entry.linkedin.add(socialUrl);
                        } else if (lowerUrl.includes('tiktok.com')) {
                            entry.tiktok.add(socialUrl);
                        }
                    }
                });
            }
        }
    }
});

// 8. Generate Output with separate columns for each social media
let results = [];
domainMap.forEach((val, domain) => {
    results.push({
        json: {
            sourceUrl: val.sourceUrl,
            companyName: val.companyName || domain,
            emails: Array.from(val.emails).join(', '),
            phones: Array.from(val.phones).join(', '),
            addresses: Array.from(val.addresses).join(' | '),
            facebookUrl: Array.from(val.facebook).join(' | '),
            instagramUrl: Array.from(val.instagram).join(' | '),
            twitterUrl: Array.from(val.twitter).join(' | '),
            youtubeUrl: Array.from(val.youtube).join(' | '),
            linkedinUrl: Array.from(val.linkedin).join(' | '),
            tiktokUrl: Array.from(val.tiktok).join(' | ')
        }
    });
});

return results;
